#include <stdio.h>

int main(void) {
    int n, size;
    char side;
    int right[61] = {0};
    int left[61] = {0};

    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%d %c", &size, &side);
        if (side == 'D')
            right[size]++;
        else
            left[size]++;
    }

    int pairs = 0;
    for (int i = 30; i <= 60; i++) {
        pairs += right[i] < left[i] ? right[i] : left[i];
    }

    printf("%d\n", pairs);
    return 0;
}
